// B4 Revenue Recovery — Stage Detection & Setup
const d = $input.item.json;

const now = new Date();
const dueDate = new Date(d['dueDate']);
const daysOverdue = isNaN(dueDate.getTime()) ? 0 : Math.max(0, Math.floor((now - dueDate) / 86400000));

const invoiceAmount = parseFloat(d['invoiceAmount']) || 0;
const formatRand = n => 'R' + n.toLocaleString('en-ZA', { minimumFractionDigits: 2 });

// Determine entry stage based on overdue days
// 0–13 days  → Stage 1 (Gentle)
// 14–20 days → Stage 2 (Firm)
// 21+ days   → Stage 3 (Final)
let entryStage = 1;
if (daysOverdue >= 21) entryStage = 3;
else if (daysOverdue >= 14) entryStage = 2;

const firstName = (d['debtorName'] || 'there').split(' ')[0];
const ownerFirstName = (d['clientName'] || 'the team').split(' ')[0];

return [{
  json: {
    ...d,
    daysOverdue,
    entryStage,
    invoiceAmount,
    invoiceAmountFormatted: formatRand(invoiceAmount),
    firstName,
    ownerFirstName,
    runAt: $now.setZone('Africa/Johannesburg').toFormat('yyyy-MM-dd HH:mm:ss')
  }
}];

