// B4 Revenue Recovery — Weekly Aggregator
const rows = $input.all();

const formatRand = n => 'R' + n.toLocaleString('en-ZA', { minimumFractionDigits: 2 });

const total = rows.length;
const byStatus = (s) => rows.filter(r => (r.json['Status'] || '').trim() === s).length;

const active = byStatus('Active');
const paid = byStatus('Paid');
const manual = byStatus('Manual Required');

const recovered = rows
  .filter(r => (r.json['Status'] || '').trim() === 'Paid')
  .reduce((acc, r) => acc + (parseFloat(r.json['Amount Recovered']) || 0), 0);

const outstanding = rows
  .filter(r => ['Active', 'Manual Required'].includes((r.json['Status'] || '').trim()))
  .reduce((acc, r) => acc + (parseFloat(r.json['Invoice Amount']) || 0), 0);

const stage1Count = rows.filter(r => (r.json['Stage'] || '').trim() === 'Stage 1').length;
const stage2Count = rows.filter(r => (r.json['Stage'] || '').trim() === 'Stage 2').length;
const stage3Count = rows.filter(r => (r.json['Stage'] || '').trim() === 'Stage 3').length;

const summary = [
  'Total invoices tracked: ' + total,
  'Active: ' + active,
  'Paid this week: ' + paid + ' (' + formatRand(recovered) + ' recovered)',
  'Awaiting manual: ' + manual,
  'Stage 1 in progress: ' + stage1Count,
  'Stage 2 in progress: ' + stage2Count,
  'Stage 3 in progress: ' + stage3Count,
  'Total still outstanding: ' + formatRand(outstanding)
].join('. ');

return [{
  json: {
    total, active, paid, manual,
    stage1Count, stage2Count, stage3Count,
    recoveredFormatted: formatRand(recovered),
    outstandingFormatted: formatRand(outstanding),
    summary,
    reportDate: new Date().toLocaleDateString('en-ZA', { timeZone: 'Africa/Johannesburg' })
  }
}];

